def solve(strike_price, premium_paid, option_type):
    """
    Computes the breakeven point of an option using a numerical bisection method.

    Args:
        strike_price (float): The strike price of the option.
        premium_paid (float): The premium paid for the option.
        option_type (str): The type of the option, either "call" or "put".

    Returns:
        float: The breakeven point of the option.
    """

    def calculate_profit(spot_price, strike, premium, opt_type):
        if opt_type == "call":
            return max(0, spot_price - strike) - premium
        elif opt_type == "put":
            return max(0, strike - spot_price) - premium
        else:
            raise ValueError("option_type must be 'call' or 'put'")

    # Define the search range for the breakeven point
    # A reasonable range would be around the strike price,
    # considering the premium.
    if option_type == "call":
        low = strike_price - premium_paid * 2  # Lower bound, could be negative but profit function handles it
        high = strike_price + premium_paid * 20 # Upper bound, assuming significant upside
    elif option_type == "put":
        low = max(0, strike_price - premium_paid * 20) # Lower bound, cannot be negative
        high = strike_price + premium_paid * 2 # Upper bound
    else:
        raise ValueError("option_type must be 'call' or 'put'")

    # Bisection method parameters
    tolerance = 1e-7  # Desired precision
    max_iterations = 1000

    for _ in range(max_iterations):
        mid = (low + high) / 2
        profit_at_mid = calculate_profit(mid, strike_price, premium_paid, option_type)

        if abs(profit_at_mid) < tolerance:
            return mid

        # Adjust the search range based on the profit
        if option_type == "call":
            # If profit is negative, the breakeven point is higher
            if profit_at_mid < 0:
                low = mid
            # If profit is positive, the breakeven point is lower
            else:
                high = mid
        elif option_type == "put":
            # If profit is negative, the breakeven point is lower
            if profit_at_mid < 0:
                high = mid
            # If profit is positive, the breakeven point is higher
            else:
                low = mid

        # If the range becomes too small, return the midpoint
        if abs(high - low) < tolerance:
            return (low + high) / 2

    # If max_iterations reached without convergence, return the last midpoint
    return (low + high) / 2
